<?php include 'config.php'; student_only();$user=$_SESSION['student'];$stmt=mysqli_prepare($conn,'SELECT * FROM issue_book WHERE student_name=? ORDER BY issue_date DESC');mysqli_stmt_bind_param($stmt,'s',$user);mysqli_stmt_execute($stmt);$loans=mysqli_stmt_get_result($stmt); ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My loans | LibraryHub</title><link rel="stylesheet" href="assets/style.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><div class="app-shell"><main class="main" style="margin-left:0;max-width:1120px;margin-right:auto;margin-left:auto"><header class="topbar"><div><p class="eyebrow">Your activity</p><h1 class="page-title">My loan history</h1></div><a class="btn secondary" href="studentdashboard.php"><i class="fa-solid fa-arrow-left"></i> My library</a></header><section class="panel"><div class="table-wrap"><table><thead><tr><th>Book ID</th><th>Issued on</th><th>Returned on</th><th>Status</th></tr></thead><tbody><?php if(mysqli_num_rows($loans)):while($loan=mysqli_fetch_assoc($loans)):$status=$loan['return_date']?'returned':'issued'; ?><tr><td>#<?php echo e($loan['book_id']); ?></td><td><?php echo e($loan['issue_date']); ?></td><td><?php echo e($loan['return_date']?:'—'); ?></td><td><span class="badge <?php echo $status; ?>"><?php echo ucfirst($status); ?></span></td></tr><?php endwhile;else:?><tr><td colspan="4" class="empty">You have no library activity yet.</td></tr><?php endif;?></tbody></table></div></section></main></div></body></html>
